export function createNormalizationLut(bytes: Uint8Array, size: number) {
  let min = 255;
  let max = 0;

  for (let index = 0; index < size; index += 1) {
    const value = bytes[index];

    if (value < min) {
      min = value;
    }
    if (value > max) {
      max = value;
    }
