  const normalized = new Uint8Array(256);

  if (max <= min) {
    return normalized;
  }

  const range = max - min;

  for (let value = min; value <= max; value += 1) {
    const ratio = (value - min) / range;
    normalized[value] = Math.round(ratio ** 0.8 * 255);
  }

  return normalized;
}

